IF ISJSON(@Catalog) <> 1 OR HASHBYTES('SHA2_256', @Catalog) <> 0xe92828ed7e836ff5e50874061d8a8fa2c899db167f7158b1ba75d9157f140ac7
    THROW 51283, 'EU catalog is incomplete or changed. Run the entire generated SQL file.', 1;
BEGIN TRY
 BEGIN TRANSACTION;
 IF EXISTS (SELECT 1 FROM ref.assetClassMaster WITH (UPDLOCK, HOLDLOCK)
 WHERE AssetClassCode NOT IN (N'105', N'110', N'115', N'120', N'121', N'125', N'135', N'140', N'150', N'155', N'160', N'162', N'176', N'181', N'195', N'196', N'210', N'212', N'215', N'218', N'220', N'225', N'226', N'227', N'228', N'230', N'235', N'242', N'244', N'245', N'250', N'255', N'260', N'265', N'275', N'280', N'285', N'295', N'310', N'315', N'335', N'340', N'345', N'346', N'350', N'375', N'380', N'385', N'390', N'452', N'455', N'462', N'465', N'475', N'480', N'512', N'514', N'575', N'590', N'650', N'665', N'670', N'672', N'675', N'695', N'700', N'701', N'710', N'715', N'720', N'750', N'755', N'765', N'770', N'775', N'795', N'800', N'805', N'810')
 OR SourceSha256<>JSON_VALUE(@Catalog,'$.sourceSha256')
 OR SourceFile<>JSON_VALUE(@Catalog,'$.sourceFile')
 OR SourceSheet<>JSON_VALUE(@Catalog,'$.sourceSheet'))
  THROW 51281, 'Existing EU catalog differs; review before replacing reference data.', 1;
 INSERT INTO ref.assetClassMaster
 (AssetClassCode, AssetClassName, AccountGroup, AccountMappingsJson, SourceFile, SourceSheet, SourceSha256)
 SELECT c.AssetClassCode, c.AssetClassName, c.AccountGroup, c.AccountMappingsJson,
 JSON_VALUE(@Catalog,'$.sourceFile'), JSON_VALUE(@Catalog,'$.sourceSheet'),
 JSON_VALUE(@Catalog,'$.sourceSha256')
 FROM OPENJSON(@Catalog,'$.classes') WITH (
 AssetClassCode nvarchar(128) '$.assetClassCode', AssetClassName nvarchar(2000) '$.assetClassName',
 AccountGroup nvarchar(256) '$.accountGroup', AccountMappingsJson nvarchar(max) '$.accountMappings' AS JSON) c
 WHERE NOT EXISTS (SELECT 1 FROM ref.assetClassMaster m WHERE m.AssetClassCode=c.AssetClassCode);
 IF EXISTS (SELECT 1 FROM OPENJSON(@Catalog,'$.classes') WITH (
 AssetClassCode nvarchar(128) '$.assetClassCode', AssetClassName nvarchar(2000) '$.assetClassName',
 AccountGroup nvarchar(256) '$.accountGroup', AccountMappingsJson nvarchar(max) '$.accountMappings' AS JSON) c
 LEFT JOIN ref.assetClassMaster m ON m.AssetClassCode=c.AssetClassCode
 WHERE m.AssetClassCode IS NULL OR m.AssetClassName<>c.AssetClassName OR m.AccountGroup<>c.AccountGroup
 OR m.AccountMappingsJson COLLATE Latin1_General_100_BIN2<>c.AccountMappingsJson COLLATE Latin1_General_100_BIN2)
  THROW 51282, 'EU catalog contents differ from the workbook. This batch was rolled back.', 1;
 COMMIT TRANSACTION;
 SELECT 16 AS VerifiedBatchClasses, COUNT(*) AS AssetClassesSoFar
 FROM ref.assetClassMaster;
END TRY
BEGIN CATCH
 IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
